CREATE TABLE IF NOT EXISTS schema_migrations (version INT PRIMARY KEY, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, active TINYINT NOT NULL DEFAULT 1, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, module_key VARCHAR(60) NOT NULL, module_label VARCHAR(100) NOT NULL, action_key VARCHAR(60) NOT NULL, action_label VARCHAR(100) NOT NULL, description TEXT NULL, version INT NOT NULL DEFAULT 1, UNIQUE KEY capability (module_key,action_key)) ENGINE=InnoDB;
CREATE TABLE role_permissions (role_id BIGINT UNSIGNED NOT NULL, permission_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission_id) REFERENCES permissions(id)) ENGINE=InnoDB;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, first_name VARCHAR(100) NOT NULL, middle_name VARCHAR(100) NULL, last_name VARCHAR(100) NOT NULL, position_title VARCHAR(150) NOT NULL, role_id BIGINT UNSIGNED NOT NULL, leader_id BIGINT UNSIGNED NULL, password_hash VARCHAR(255) NOT NULL, require_password_change TINYINT NOT NULL DEFAULT 1, session_version INT NOT NULL DEFAULT 1, active TINYINT NOT NULL DEFAULT 1, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(leader_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE login_attempts (attempt_key CHAR(64) PRIMARY KEY, failures INT NOT NULL DEFAULT 0, window_started DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE areas (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL UNIQUE, active TINYINT NOT NULL DEFAULT 1, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE specifics (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, area_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, active TINYINT NOT NULL DEFAULT 1, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY specific_name(area_id,name), FOREIGN KEY(area_id) REFERENCES areas(id)) ENGINE=InnoDB;
CREATE TABLE assets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, specific_id BIGINT UNSIGNED NOT NULL, asset_number VARCHAR(100) NOT NULL UNIQUE, active TINYINT NOT NULL DEFAULT 1, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(specific_id) REFERENCES specifics(id)) ENGINE=InnoDB;
CREATE TABLE locations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, specific_id BIGINT UNSIGNED NOT NULL, asset_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, code VARCHAR(100) NOT NULL UNIQUE, active TINYINT NOT NULL DEFAULT 1, archive_date DATE NULL, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(specific_id) REFERENCES specifics(id), FOREIGN KEY(asset_id) REFERENCES assets(id)) ENGINE=InnoDB;
CREATE TABLE categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, parent_id BIGINT UNSIGNED NULL, name VARCHAR(150) NOT NULL, folder_name VARCHAR(150) NOT NULL, description TEXT NULL, active TINYINT NOT NULL DEFAULT 1, created_by BIGINT UNSIGNED NOT NULL, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(parent_id) REFERENCES categories(id), FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE files (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, original_name VARCHAR(255) NOT NULL, storage_name VARCHAR(100) NOT NULL UNIQUE, size BIGINT UNSIGNED NOT NULL, mime_type VARCHAR(150) NOT NULL, fingerprint CHAR(64) NOT NULL, extension VARCHAR(10) NOT NULL, purpose VARCHAR(30) NOT NULL DEFAULT 'upload', domain VARCHAR(10) NULL, document_id BIGINT UNSIGNED NULL, uploaded_by BIGINT UNSIGNED NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'pending', approved_by BIGINT UNSIGNED NULL, approved_at DATETIME NULL, rejected_by BIGINT UNSIGNED NULL, rejected_at DATETIME NULL, rejection_reason TEXT NULL, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(uploaded_by) REFERENCES users(id), FOREIGN KEY(approved_by) REFERENCES users(id), FOREIGN KEY(rejected_by) REFERENCES users(id), INDEX document_files(domain,document_id,status)) ENGINE=InnoDB;
CREATE TABLE softcopy_documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, document_number VARCHAR(100) NOT NULL UNIQUE, series_number VARCHAR(100) NULL, title VARCHAR(255) NOT NULL, category_id BIGINT UNSIGNED NOT NULL, current_revision_id BIGINT UNSIGNED NULL, status VARCHAR(30) NOT NULL DEFAULT 'active', previous_status VARCHAR(30) NULL, created_by BIGINT UNSIGNED NOT NULL, creation_source VARCHAR(20) NOT NULL, creation_reason TEXT NOT NULL, source_request_id BIGINT UNSIGNED NULL, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES categories(id), FOREIGN KEY(created_by) REFERENCES users(id), INDEX softcopy_status(status,title)) ENGINE=InnoDB;
CREATE TABLE softcopy_revisions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, document_id BIGINT UNSIGNED NOT NULL, revision_number INT UNSIGNED NOT NULL, reason TEXT NOT NULL, effective_date DATE NOT NULL, page_number INT UNSIGNED NOT NULL, series_number VARCHAR(100) NULL, document_title VARCHAR(255) NOT NULL, previous_revision_level VARCHAR(30) NULL, new_revision_level VARCHAR(30) NOT NULL, previous_effective_date DATE NULL, new_effective_date DATE NOT NULL, date_received DATE NOT NULL, date_released DATE NOT NULL, approval_date DATE NOT NULL, file_id BIGINT UNSIGNED NOT NULL UNIQUE, uploaded_by BIGINT UNSIGNED NOT NULL, approved_by BIGINT UNSIGNED NOT NULL, approved_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY revision_per_document(document_id,revision_number), FOREIGN KEY(document_id) REFERENCES softcopy_documents(id), FOREIGN KEY(file_id) REFERENCES files(id), FOREIGN KEY(uploaded_by) REFERENCES users(id), FOREIGN KEY(approved_by) REFERENCES users(id)) ENGINE=InnoDB;
ALTER TABLE softcopy_documents ADD CONSTRAINT current_revision_fk FOREIGN KEY(current_revision_id) REFERENCES softcopy_revisions(id);
CREATE TABLE revision_artifacts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, revision_id BIGINT UNSIGNED NOT NULL, artifact_type VARCHAR(20) NOT NULL, file_id BIGINT UNSIGNED NOT NULL UNIQUE, source_fingerprint CHAR(64) NOT NULL, generator_version VARCHAR(50) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY artifact_source(revision_id,artifact_type,source_fingerprint), FOREIGN KEY(revision_id) REFERENCES softcopy_revisions(id), FOREIGN KEY(file_id) REFERENCES files(id)) ENGINE=InnoDB;
CREATE TABLE hardcopy_documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, area_id BIGINT UNSIGNED NOT NULL, specific_id BIGINT UNSIGNED NOT NULL, asset_id BIGINT UNSIGNED NOT NULL, location_id BIGINT UNSIGNED NULL UNIQUE, sequence_number VARCHAR(100) NULL, retention_enabled TINYINT NOT NULL DEFAULT 0, retention_start_date DATE NULL, retention_end_date DATE NULL, holder_id BIGINT UNSIGNED NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'active', previous_status VARCHAR(30) NULL, created_by BIGINT UNSIGNED NOT NULL, creation_source VARCHAR(20) NOT NULL, creation_reason TEXT NOT NULL, source_request_id BIGINT UNSIGNED NULL, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(area_id) REFERENCES areas(id), FOREIGN KEY(specific_id) REFERENCES specifics(id), FOREIGN KEY(asset_id) REFERENCES assets(id), FOREIGN KEY(location_id) REFERENCES locations(id), FOREIGN KEY(holder_id) REFERENCES users(id), FOREIGN KEY(created_by) REFERENCES users(id), INDEX hardcopy_status(status,title)) ENGINE=InnoDB;
CREATE TABLE workflows (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, workflow_key VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, description TEXT NULL, request_type VARCHAR(50) NOT NULL, active TINYINT NOT NULL DEFAULT 0, active_request_type VARCHAR(50) GENERATED ALWAYS AS (CASE WHEN active=1 THEN request_type ELSE NULL END) STORED, UNIQUE KEY one_active_workflow(active_request_type), INDEX workflow_type(request_type), created_by BIGINT UNSIGNED NOT NULL, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE workflow_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, workflow_id BIGINT UNSIGNED NOT NULL, version_number INT UNSIGNED NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'draft', graph JSON NOT NULL, created_by BIGINT UNSIGNED NOT NULL, published_at DATETIME NULL, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY workflow_version(workflow_id,version_number), FOREIGN KEY(workflow_id) REFERENCES workflows(id), FOREIGN KEY(created_by) REFERENCES users(id), INDEX publication(workflow_id,status)) ENGINE=InnoDB;
CREATE TABLE document_approvers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, domain VARCHAR(10) NOT NULL, document_id BIGINT UNSIGNED NOT NULL, config JSON NOT NULL, configured_by BIGINT UNSIGNED NOT NULL, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY document_config(domain,document_id), FOREIGN KEY(configured_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reference VARCHAR(50) NOT NULL UNIQUE, type VARCHAR(50) NOT NULL, softcopy_id BIGINT UNSIGNED NULL, hardcopy_id BIGINT UNSIGNED NULL, requested_by BIGINT UNSIGNED NOT NULL, payload JSON NOT NULL, workflow_version_id BIGINT UNSIGNED NULL, snapshot JSON NULL, approver_config JSON NULL, current_node VARCHAR(50) NULL, status VARCHAR(30) NOT NULL DEFAULT 'draft', result JSON NULL, version INT NOT NULL DEFAULT 1, submitted_at DATETIME NULL, completed_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(softcopy_id) REFERENCES softcopy_documents(id), FOREIGN KEY(hardcopy_id) REFERENCES hardcopy_documents(id), FOREIGN KEY(requested_by) REFERENCES users(id), FOREIGN KEY(workflow_version_id) REFERENCES workflow_versions(id), INDEX request_queue(status,type,requested_by), CHECK (softcopy_id IS NULL OR hardcopy_id IS NULL)) ENGINE=InnoDB;
CREATE TABLE workflow_steps (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, request_id BIGINT UNSIGNED NOT NULL, node_key VARCHAR(50) NOT NULL, label VARCHAR(120) NOT NULL, assignment JSON NOT NULL, candidates JSON NOT NULL, assigned_user_id BIGINT UNSIGNED NULL, assigned_name VARCHAR(255) NULL, assigned_position VARCHAR(150) NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', decision VARCHAR(20) NULL, comments TEXT NULL, acting_user_id BIGINT UNSIGNED NULL, acting_name VARCHAR(255) NULL, acting_position VARCHAR(150) NULL, assigned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, acted_at DATETIME NULL, version INT NOT NULL DEFAULT 1, FOREIGN KEY(request_id) REFERENCES requests(id), FOREIGN KEY(assigned_user_id) REFERENCES users(id), FOREIGN KEY(acting_user_id) REFERENCES users(id), INDEX pending_steps(status,request_id)) ENGINE=InnoDB;
CREATE TABLE workflow_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, request_id BIGINT UNSIGNED NOT NULL, step_id BIGINT UNSIGNED NULL, action VARCHAR(50) NOT NULL, user_id BIGINT UNSIGNED NOT NULL, user_name VARCHAR(255) NOT NULL, position_title VARCHAR(150) NOT NULL, before_state JSON NULL, after_state JSON NULL, comments TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(request_id) REFERENCES requests(id), FOREIGN KEY(step_id) REFERENCES workflow_steps(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE transfers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, request_id BIGINT UNSIGNED NOT NULL UNIQUE, hardcopy_id BIGINT UNSIGNED NOT NULL, origin JSON NOT NULL, destination JSON NOT NULL, current_holder_id BIGINT UNSIGNED NOT NULL, recipient_id BIGINT UNSIGNED NOT NULL, document_copy_number VARCHAR(100) NOT NULL, reason TEXT NOT NULL, comments TEXT NULL, status VARCHAR(40) NOT NULL DEFAULT 'for_transfer', recipient_status VARCHAR(20) NOT NULL DEFAULT 'pending', transferred_by BIGINT UNSIGNED NULL, transferred_at DATETIME NULL, accepted_by BIGINT UNSIGNED NULL, accepted_at DATETIME NULL, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(request_id) REFERENCES requests(id), FOREIGN KEY(hardcopy_id) REFERENCES hardcopy_documents(id), FOREIGN KEY(current_holder_id) REFERENCES users(id), FOREIGN KEY(recipient_id) REFERENCES users(id), FOREIGN KEY(transferred_by) REFERENCES users(id), FOREIGN KEY(accepted_by) REFERENCES users(id), INDEX transfer_queue(status,recipient_id)) ENGINE=InnoDB;
CREATE TABLE access_grants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, request_id BIGINT UNSIGNED NOT NULL UNIQUE, domain VARCHAR(10) NOT NULL, document_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, granted_by BIGINT UNSIGNED NOT NULL, granted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, expires_at DATETIME NOT NULL, revoked_at DATETIME NULL, revoked_by BIGINT UNSIGNED NULL, reason TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'access_granted', version INT NOT NULL DEFAULT 1, FOREIGN KEY(request_id) REFERENCES requests(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(granted_by) REFERENCES users(id), FOREIGN KEY(revoked_by) REFERENCES users(id), INDEX access_check(domain,document_id,user_id,status,expires_at)) ENGINE=InnoDB;
CREATE TABLE assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, softcopy_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, assigned_by BIGINT UNSIGNED NOT NULL, assigned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, active TINYINT NOT NULL DEFAULT 1, version INT NOT NULL DEFAULT 1, UNIQUE KEY assigned_document(softcopy_id,user_id), FOREIGN KEY(softcopy_id) REFERENCES softcopy_documents(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(assigned_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE disposals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, request_id BIGINT UNSIGNED NOT NULL UNIQUE, domain VARCHAR(10) NOT NULL, document_id BIGINT UNSIGNED NOT NULL, previous_status VARCHAR(30) NOT NULL, previous_state JSON NOT NULL, disposal_action VARCHAR(20) NOT NULL, remarks TEXT NOT NULL, disposed_by BIGINT UNSIGNED NOT NULL, disposed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(request_id) REFERENCES requests(id), FOREIGN KEY(disposed_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, domain VARCHAR(10) NOT NULL, document_id BIGINT UNSIGNED NOT NULL, previous_status VARCHAR(30) NOT NULL, new_status VARCHAR(30) NOT NULL, action VARCHAR(60) NOT NULL, user_id BIGINT UNSIGNED NOT NULL, remarks TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), INDEX lifecycle(domain,document_id,created_at)) ENGINE=InnoDB;
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, title VARCHAR(150) NOT NULL, message TEXT NOT NULL, request_id BIGINT UNSIGNED NULL, read_at DATETIME NULL, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(request_id) REFERENCES requests(id), INDEX inbox(user_id,read_at,created_at)) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, username VARCHAR(80) NOT NULL, role_name VARCHAR(120) NOT NULL, module VARCHAR(60) NOT NULL, action VARCHAR(80) NOT NULL, entity_id BIGINT UNSIGNED NULL, before_state JSON NULL, after_state JSON NULL, reason TEXT NULL, request_id BIGINT UNSIGNED NULL, http_method VARCHAR(10) NOT NULL, path VARCHAR(255) NOT NULL, ip_address VARCHAR(64) NOT NULL, user_agent VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX audit_module(module,action,created_at), INDEX audit_user(user_id,created_at)) ENGINE=InnoDB;
CREATE TABLE sequences (sequence_key VARCHAR(80) PRIMARY KEY, value BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB;
CREATE TABLE settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, setting_key VARCHAR(80) NOT NULL UNIQUE, value JSON NOT NULL, version INT NOT NULL DEFAULT 1, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
INSERT INTO schema_migrations(version) VALUES(1);
